import { styled } from '@hexa-ui/theme';

import { DDT_COLORS, DDT_SPACING } from '../../DrillDownTable.styles';

export const DDTRow = styled('div', {
  display: 'flex',
  flexDirection: 'row',
  minHeight: DDT_SPACING.rowHeight,
  backgroundColor: 'var(--ddt-row-bg, #ffffff)',
  boxSizing: 'border-box',
});

export const DDTAxisCell = styled('div', {
  flexGrow: 0,
  flexShrink: 0,
  flexBasis: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  width: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  minWidth: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  maxWidth: `var(--ddt-axis-width, ${DDT_SPACING.axisDefaultWidth})`,
  display: 'flex',
  alignItems: 'center',
  padding: '0 8px',
  boxSizing: 'border-box',
  overflow: 'hidden',
  borderRight: `1px solid ${DDT_COLORS.border.header}`,
});

export const DDTDriverContent = styled('div', {
  display: 'flex',
  alignItems: 'center',
  gap: '4px',
  paddingLeft: 'var(--ddt-indent, 0px)',
  minWidth: 0,
  flex: 1,
});

export const DDTChevronButton = styled('button', {
  backgroundColor: '#f6f6f6',
  border: 'none',
  cursor: 'pointer',
  padding: '4px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: '24px',
  height: '24px',
  flexShrink: 0,
  borderRadius: '512px',
  color: DDT_COLORS.chevron,
  '&:hover': {
    backgroundColor: '#ececec',
  },
  '&:focus-visible': {
    outline: `2px solid ${DDT_COLORS.chevron}`,
    outlineOffset: '1px',
  },
});

export const DDTChevronWrapper = styled('span', {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  transition: 'transform 0.2s ease',
  color: DDT_COLORS.chevron,
  variants: {
    expanded: {
      true: { transform: 'rotate(180deg)' },
      false: { transform: 'rotate(0deg)' },
    },
  },
  defaultVariants: {
    expanded: 'false',
  },
});

export const DDTChevronSpacer = styled('span', {
  width: '24px',
  height: '24px',
  flexShrink: 0,
  display: 'inline-block',
});

export const DDTDriverLabel = styled('span', {
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 400,
  fontSize: '12px',
  color: DDT_COLORS.text.primary,
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  minWidth: 0,
});

export const DDTSquareBrandImg = styled('img', {
  width: '24px',
  height: '24px',
  borderRadius: '4px',
  objectFit: 'cover',
  flexShrink: 0,
  display: 'block',
});

export const DDTDataGroupsWrapper = styled('div', {
  display: 'flex',
  flexDirection: 'row',
  flex: 1,
  minWidth: 0,
});

export const DDTDataGroup = styled('div', {
  flex: 1,
  display: 'flex',
  flexDirection: 'row',
  borderRight: `1px solid ${DDT_COLORS.border.group}`,
  boxSizing: 'border-box',
  minWidth: 0,
  variants: {
    isLast: {
      true: { borderRight: 'none' },
    },
  },
});

export const DDTCell = styled('div', {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  padding: '0 8px',
  boxSizing: 'border-box',
  fontFamily: "'Work Sans', sans-serif",
  fontWeight: 400,
  fontSize: '14px',
  color: DDT_COLORS.text.primary,
  borderRight: `1px solid ${DDT_COLORS.border.row}`,
  variants: {
    isLast: {
      true: { borderRight: 'none' },
    },
  },
});
